---- MONITORS ----
------------------

-- See https://wiki.hypr.land/Configuring/Basics/Monitors/
-- Fallback for any display not named in the generated file below.
hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto",
    scale    = "auto",
})

-- Per-monitor layout written by hyprmoncfg (SUPER+SHIFT+M).
-- This require() is what makes the arrangement survive a restart — hyprmoncfg
-- applies changes live via hyprctl, but without loading its file here the
-- layout reverts to position="auto" on the next Hyprland start.
-- Loaded AFTER the generic rule above so its specific desc: entries win.
pcall(require, "hyprmoncfg-monitors")


