-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

-- Layer rules also return a handle.
-- local overlayLayerRule = hl.layer_rule({
--     name  = "no-anim-overlay",
--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- Blur the wallpaper behind waybar so its translucent background reads as
-- glass instead of a flat black slab. ignore_alpha skips the fully clear
-- region around the bar's rounded corners, which would otherwise blur as a
-- visible rectangle.
hl.layer_rule({
    name  = "blur-waybar",
    match = { namespace = "^waybar$" },
    blur = true,
    ignore_alpha = 0.2,
})

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})
-- Nvidia
-- Video decode goes to the INTEL iGPU (iHD), not the dGPU.
--
-- Why: Hyprland advertises /dev/dri/renderD128 (pci 00:02.0, Intel) as the
-- dmabuf device to clients. With LIBVA_DRIVER_NAME=nvidia, Chromium/Brave
-- decoded on renderD129 (the 4070) and then tried to import that buffer into
-- a GL context bound to the Intel node. The cross-GPU import fails with
--   eglCreateImage failed with 0x00003009   (EGL_BAD_MATCH)
--   SharedImageManager::ProduceSkia ... CompoundImageBacking
-- and video breaks everywhere except YouTube (which falls back to software
-- decode for VP9/AV1). Decoding on the same node the compositor hands out
-- fixes it. Requires the intel-media-driver package.
hl.env("LIBVA_DRIVER_NAME", "iHD")
hl.env("__GLX_VENDOR_LIBRARY_NAME","nvidia")
-- NVD_BACKEND is read only by libva-nvidia-driver, which is no longer in use:
-- hl.env("NVD_BACKEND","direct")
hl.env("ELECTRON_OZONE_PLATFORM_HINT","auto")

-- AUTOSTART
hl.on("hyprland.start", function()
hl.exec_cmd("waybar")
hl.exec_cmd("hyprpaper")
-- Notification daemon. swaync is preferred because it provides a control
-- centre (the panel the clock opens); dunst has no such panel. Falls back to
-- dunst so notifications keep working if swaync is ever absent. Only one may
-- own the org.freedesktop.Notifications name, hence the either/or.
hl.exec_cmd("sh -c 'command -v swaync >/dev/null 2>&1 && exec swaync || exec dunst'")
hl.exec_cmd("wl-gammarelay-rs")
hl.exec_cmd("wl-paste --watch cliphist store")
hl.exec_cmd("hypridle")
-- nm-applet deliberately NOT started: its tray icon duplicates waybar's own
-- network module, giving two wifi indicators. Waybar covers the status, and
-- clicking it opens nm-connection-editor for the full connection UI.
-- (The command was also misspelled "nm-amplet" here, so it never ran anyway.)
-- hl.exec_cmd("nm-applet --indicator")
end)

-- Brightnes

-- Volume
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%+"))
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"))
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"))

-- Screenshot
hl.bind("SUPER + SHIFT + S", hl.dsp.exec_cmd("grim -g \"$(slurp)\" - | wl-copy"))
-- Brightness via wl-gammarelay-rs.
-- Routed through a wrapper because the raw UpdateBrightness call does not clamp:
-- holding the key drives the value past 1.0 or below 0.0 and blacks out the panel.
-- The script clamps to 0.1-1.0 and keeps waybar's readout in sync.
local brightness = "$HOME/.config/waybar/scripts/brightness.sh"
hl.bind("XF86MonBrightnessUp",   hl.dsp.exec_cmd(brightness .. " up"),   { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd(brightness .. " down"), { locked = true, repeating = true })


hl.env("MOZ_ENABLE_WAYLAND", "1")

-- App launcher on the Windows key alone. This is a *release* bind: SUPER_L
-- fires when the key comes back up, since a modifier held down cannot itself
-- be a press-trigger. Caveat: Hyprland also fires this when you release SUPER
-- after a combo like SUPER+Q, so the launcher can appear unbidden. Delete
-- these two lines if that becomes irritating — the bar button and SUPER+R
-- both still open it.
-- pkill -x (exact name): a bare "pkill rofi" also matches
-- power-profiles-daemon, because "rofi" is a substring of "p-rofi-les".
hl.bind("SUPER + SUPER_L", hl.dsp.exec_cmd("pkill -x rofi || rofi -show drun"), { release = true })

-- Blur the wallpaper behind rofi so the launcher matches the bar and terminal.
hl.layer_rule({
    name  = "blur-rofi",
    match = { namespace = "^rofi$" },
    blur = true,
    ignore_alpha = 0.2,
})

-- Same for swaync's two surfaces, otherwise whatever is underneath reads
-- straight through the translucent cards and makes the text hard to follow.
hl.layer_rule({
    name  = "blur-swaync-notifications",
    match = { namespace = "^swaync-notification-window$" },
    blur = true,
    ignore_alpha = 0.2,
})

hl.layer_rule({
    name  = "blur-swaync-control-center",
    match = { namespace = "^swaync-control-center$" },
    blur = true,
    ignore_alpha = 0.2,
})

-- Added by hyprmoncfg: its generated monitor rules load last, so nothing before this can override the applied layout.
dofile(os.getenv("HOME") .. "/.config/hypr/hyprmoncfg-monitors.lua")

-- Terminal: clear translucency instead of frosted glass. Blur stays enabled
-- globally (waybar, rofi and swaync still rely on it via their layer rules);
-- this rule opts kitty out so the wallpaper reads sharply through it.
--
-- Side effect worth knowing: decoration.blur.brightness (0.85) only applies to
-- blurred surfaces, so removing blur also removes that dimming. kitty's own
-- background_opacity is now the only thing darkening the window.
hl.window_rule({
    name  = "kitty-no-blur",
    match = { class = "^kitty$" },
    no_blur = true,
})

-------------------------------
---- IDLE / LOCK / SESSION ----
-------------------------------

-- Lid close locks the session; opening it wakes the displays. `locked = true`
-- is essential — without it the bind is ignored while the session is already
-- locked, so opening the lid would leave the screen dark.
hl.bind("switch:on:Lid Switch",  hl.dsp.exec_cmd("loginctl lock-session"),        { locked = true })
hl.bind("switch:off:Lid Switch", hl.dsp.exec_cmd("hyprctl dispatch 'hl.dsp.dpms(\"on\")'"), { locked = true })

-- Lock now.
hl.bind(mainMod .. " + L", hl.dsp.exec_cmd("pidof hyprlock || hyprlock"))

-- Power menu (same rofi card the waybar button opens).
hl.bind(mainMod .. " + ESCAPE", hl.dsp.exec_cmd("$HOME/.config/rofi/powermenu.sh"))

-- Clipboard history. The cliphist daemon has been collecting all along; this
-- is the missing viewer. SUPER+V is already taken by float-toggle, hence SHIFT.
hl.bind(mainMod .. " + SHIFT + V", hl.dsp.exec_cmd(
    "sh -c 'cliphist list | rofi -dmenu -p Clipboard -theme " ..
    "$HOME/.config/rofi/launcher.rasi | cliphist decode | wl-copy'"))
